import pLimit from "p-limit";
import { db } from "../../db";
import { searchClient } from "../../search";

const limit = pLimit(5);

export async function reindexAll() {
  const products = await db.product.findMany({ select: { id: true, title: true } });
  await Promise.all(products.map((p) => limit(() => searchClient.index("products").addDocuments([p]))));
  return products.length;
}

import pMap from "p-map";
import { sendReceipt } from "../email/receipts";

export async function sendReceipts(orderIds: string[]) {
  await pMap(orderIds, async (id) => sendReceipt(id), { concurrency: 10 });
  const summary = await Promise.all([countSent(), countFailed()]);
  return summary;
}

const BATCH_SIZE = 25;

export async function upsertInBatches<T>(rows: T[], upsert: (row: T) => Promise<void>) {
  for (let i = 0; i < rows.length; i += BATCH_SIZE) {
    const chunk = rows.slice(i, i + BATCH_SIZE);
    await Promise.all(chunk.map(async (row) => upsert(row)));
  }
}

