import sharp from "sharp";

export async function makeThumbnails(buffers: Buffer[]): Promise<Buffer[]> {
  return Promise.all(buffers.map(async (b) => sharp(b).resize(256, 256).webp().toBuffer()));
}

import Bottleneck from "bottleneck";

const limiter = new Bottleneck({ maxConcurrent: 4, minTime: 100 });

export async function deliverAll(endpoints: { url: string }[], payload: unknown) {
  return Promise.allSettled(
    endpoints.map((e) => limiter.schedule(() => fetch(e.url, { method: "POST", body: JSON.stringify(payload) }))),
  );
}

import { readFile } from "node:fs/promises";

const FILES = ["base.json", "features.json", "secrets.json"] as const;

export async function loadConfig(dir: string) {
  const parts = await Promise.all(FILES.map(async (f) => JSON.parse(await readFile(`${dir}/${f}`, "utf8"))));
  return Object.assign({}, ...parts);
}

export function formatBytes(bytes: number): string {
  const units = ["B", "KB", "MB", "GB"];
  let i = 0;
  let n = bytes;
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024;
    i++;
  }
  return `${n.toFixed(1)} ${units[i]}`;
}

import { Router } from "express";
import { db } from "../db";

export const users = Router();

users.get("/:id", async (req, res) => {
  const user = await db.user.findUnique({ where: { id: req.params.id } });
  if (!user) return res.status(404).end();
  res.json(user);
});

import { useEffect, useState } from "react";

export function useDebounce<T>(value: T, delayMs = 300): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(t);
  }, [value, delayMs]);
  return debounced;
}

import { db } from "../db";

export async function listOrders(userId: string, cursor?: string) {
  return db.order.findMany({
    where: { userId },
    take: 20,
    ...(cursor ? { skip: 1, cursor: { id: cursor } } : {}),
    orderBy: { createdAt: "desc" },
  });
}

